// FF + MVU GameStart v1.4 — global, cardless, branch-local.
(() => {
  const scriptWindow = window;
  const host = (() => {
    try { return window.parent && window.parent !== window ? window.parent : window; }
    catch (error) { return window; }
  })();
  const hostDoc = host.document;

  const runtimeScopes = [...new Set([scriptWindow, host].filter(Boolean))];

  function runtimeFunction(name) {
    for (const scope of runtimeScopes) {
      if (typeof scope?.[name] === 'function') return scope[name].bind(scope);
    }
    return null;
  }

  function getSillyTavern() {
    for (const scope of runtimeScopes) {
      if (scope?.SillyTavern) return scope.SillyTavern;
    }
    return null;
  }

  function getTavernEvents() {
    for (const scope of runtimeScopes) {
      if (scope?.tavern_events) return scope.tavern_events;
    }
    return {};
  }

  if (typeof host.__FFMVU_GAMESTART_CLEANUP__ === 'function') {
    try { host.__FFMVU_GAMESTART_CLEANUP__(); } catch (error) {}
  }

  const MENU_HTML = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FF + MVU Game Start</title>
<style>
:root{--a:#00e5ff;--t:#e0f7fa;--s:#81d4fa;--b:rgba(0,229,255,.3)}*{box-sizing:border-box}body{margin:0;padding:14px;font:14px 'Segoe UI',sans-serif;color:var(--t);background:linear-gradient(135deg,#001f3f,#003366,#006064)}.box{max-width:900px;margin:auto}.head{font-size:20px;font-weight:700;color:var(--a);border-bottom:1px solid var(--b);padding-bottom:10px;margin-bottom:12px}.sub{color:var(--s);margin-bottom:14px}.sec{background:rgba(0,0,0,.18);border:1px solid rgba(0,229,255,.17);border-radius:7px;padding:12px;margin-bottom:12px}.title{font-weight:700;color:var(--a);margin-bottom:10px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 14px}.row{display:flex;align-items:center;gap:8px}.row label{flex:0 0 105px}.row input,.row textarea{min-width:0;flex:1;background:rgba(0,0,0,.35);color:#d7f3ff;border:1px solid var(--b);border-radius:4px;padding:7px}.stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 14px}.stat{display:flex;align-items:center;gap:8px}.stat span:first-child{flex:1}.stat button{width:30px;height:30px;background:rgba(0,229,255,.1);color:var(--a);border:1px solid var(--b);border-radius:4px;cursor:pointer}.stat button:disabled{opacity:.35}.val{width:28px;text-align:center;font-weight:700}.save{width:100%;padding:11px;background:rgba(0,229,255,.15);color:var(--a);border:1px solid var(--a);border-radius:5px;font-weight:700;cursor:pointer}.save:disabled{opacity:.5}.status{min-height:20px;margin-top:9px;color:#ffd54f}@media(max-width:620px){.grid,.stats{grid-template-columns:1fr}}
</style></head><body><div class="box"><div class="head">FF + MVU · Character Creation Setup</div><div class="sub">Setup your starting attributes, equipment, and identity.</div>
<div class="sec"><div class="title">World Start</div><div class="grid">
<div class="row"><label>Date</label><input class="gs-date" value="Day 1"></div><div class="row"><label>Time</label><input class="gs-time" value="08:00" placeholder="HH:MM"></div><div class="row"><label>Weather</label><input class="gs-weather" value="Clear"></div><div class="row"><label>Location</label><input class="gs-location" value="Unspecified"></div>
</div></div>
<div class="sec"><div class="title">Character</div><div class="grid">
<div class="row"><label>Name</label><input class="gs-name" value="{{user}}"></div><div class="row"><label>Age</label><input class="gs-age" value="18"></div><div class="row"><label>Gender</label><input class="gs-gender" value="Unspecified"></div><div class="row"><label>Race</label><input class="gs-race" value="Human"></div><div class="row"><label>Occupation</label><input class="gs-occ" value="Adventurer"></div><div class="row"><label>Mental state</label><input class="gs-mental" value="Calm"></div><div class="row"><label>Charisma</label><input type="number" class="gs-charisma" value="80" min="80" max="100" step="1" title="Fixed at character creation; cannot be increased via leveling."></div><div class="row"><label>Level</label><input type="number" class="gs-level" value="1" min="1" max="140"></div><div class="row"><label>EXP</label><input type="number" class="gs-exp" value="0" min="0"></div><div class="row"><label>Core points</label><input type="number" class="gs-core" value="0" min="0"></div>
</div></div>
<div class="sec"><div class="title">Core Attributes · Points Remaining: <span class="gs-points">50</span></div><div class="stats gs-stat-rows">
${['str:Strength','agi:Agility','con:Constitution','int:Intelligence','wis:Wisdom'].map(x=>{const [k,n]=x.split(':');return `<div class="stat" data-stat="${k}"><span>${n}</span><button class="minus">−</button><span class="val">5</span><button class="plus">+</button></div>`}).join('')}
</div><div style="margin-top:8px;color:var(--s);font-size:12px">Charisma is separate: 80–100 at creation and does not consume Core Attribute points.</div></div>
<div class="sec"><div class="title">Optional Starting Weapon</div><div class="row"><textarea class="gs-weapon" rows="3" placeholder="Leave empty to start unarmed, or describe preferences for one model-generated weapon."></textarea></div></div>
<button class="save">Confirm & Start Journey</button><div class="status"></div></div>
<script>(()=>{const MAX=50,BASE=5,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],status=$('.status'),btn=$('.save');const value=(s,f='')=>$(s)?.value?.trim()||f;function remain(){return MAX-$$('.stat').reduce((a,r)=>a+(Number(r.querySelector('.val').textContent)||BASE)-BASE,0)}function recalc(){const r=remain();$('.gs-points').textContent=String(r);$$('.stat').forEach(row=>{const v=Number(row.querySelector('.val').textContent)||BASE;row.querySelector('.minus').disabled=v<=BASE;row.querySelector('.plus').disabled=r<=0});if(!btn.dataset.saving)btn.disabled=r<0;return r}$$('.stat').forEach(row=>{row.querySelector('.minus').onclick=()=>{const e=row.querySelector('.val'),v=Number(e.textContent)||BASE;if(v>BASE)e.textContent=String(v-1);recalc()};row.querySelector('.plus').onclick=()=>{const e=row.querySelector('.val'),v=Number(e.textContent)||BASE;if(remain()>0)e.textContent=String(v+1);recalc()}});btn.onclick=()=>{if(recalc()<0)return;const stats={};$$('.stat').forEach(r=>stats[r.dataset.stat]=Number(r.querySelector('.val').textContent)||BASE);const payload={date:value('.gs-date','Day 1'),time:value('.gs-time','08:00'),weather:value('.gs-weather','Clear'),location:value('.gs-location','Unspecified'),name:value('.gs-name','{{user}}'),age:value('.gs-age','18'),gender:value('.gs-gender','Unspecified'),race:value('.gs-race','Human'),occupation:value('.gs-occ','Adventurer'),mental:value('.gs-mental','Calm'),charisma:Math.max(80,Math.min(100,parseInt(value('.gs-charisma','80'),10)||80)),level:Math.max(1,Math.min(140,parseInt(value('.gs-level','1'),10)||1)),exp:Math.max(0,parseInt(value('.gs-exp','0'),10)||0),core:Math.max(0,parseInt(value('.gs-core','0'),10)||0),weaponRequest:value('.gs-weapon',''),stats};btn.dataset.saving='1';btn.disabled=true;btn.textContent='Saving...';status.textContent='Saving to active branch...';parent.postMessage({type:'FFMVU_GAMESTART_SAVE',payload},'*')};addEventListener('message',e=>{if(e.data?.type==='FFMVU_GAMESTART_OK'){status.style.color='#50fa7b';status.textContent='Saved. The game is ready.'}else if(e.data?.type==='FFMVU_GAMESTART_ERROR'){delete btn.dataset.saving;btn.disabled=false;btn.textContent='Confirm & Start Journey';status.style.color='#ff8a80';status.textContent='Save error: '+(e.data.message||'unknown');recalc()}});recalc()})();<\/script></body></html>`;

  let disposed = false;
  let overlay = null;
  let iframe = null;
  let activeToken = '';
  let activeProvisional = false;
  let poll = null;
  const subscriptions = [];
  const clone = value => typeof structuredClone === 'function' ? structuredClone(value) : JSON.parse(JSON.stringify(value));
  const tupleSet = (object, key, value, label) => {
    if (!Array.isArray(object[key]) || object[key].length < 2) object[key] = [value, label];
    else object[key][0] = value;
  };
  const getApi = () => {
    for (const scope of runtimeScopes) {
      if (scope?.FFMVU) return scope.FFMVU;
    }
    return null;
  };
  const escapeAttr = value => String(value).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

  function normalizeClock(value) {
    const match = /^\s*(\d{1,2}):(\d{2})\s*$/.exec(String(value ?? ''));
    if (!match) return null;
    const hour = Number(match[1]);
    const minute = Number(match[2]);
    if (!Number.isInteger(hour) || !Number.isInteger(minute) || hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;
    return String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0');
  }

  function currentUserName() {
    const st = getSillyTavern();
    try {
      const name = st?.getContext?.()?.name1;
      if (name) return name;
    } catch (error) {}
    for (const scope of runtimeScopes) {
      if (scope?.name1) return scope.name1;
    }
    return 'Player';
  }
  function removeOverlay() {
    if (overlay) overlay.remove();
    overlay = null; iframe = null; activeToken = ''; activeProvisional = false;
  }
  function showOverlay(token, provisional = false) {
    if (overlay && activeToken === token) return;
    if (overlay && activeProvisional && !provisional) { activeToken = token; activeProvisional = false; return; }
    removeOverlay();
    activeToken = token; activeProvisional = provisional;
    overlay = hostDoc.createElement('div');
    overlay.id = 'ffmvu-gamestart-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:49000;background:rgba(0,0,0,.86);backdrop-filter:blur(3px);display:flex;align-items:center;justify-content:center;padding:12px;box-sizing:border-box';
    iframe = hostDoc.createElement('iframe');
    iframe.title = 'FF + MVU Game Start';
    iframe.style.cssText = 'width:min(940px,100%);height:min(900px,94vh);border:1px solid rgba(0,229,255,.45);border-radius:8px;background:#001f3f;box-shadow:0 10px 45px rgba(0,0,0,.7)';
    iframe.srcdoc = MENU_HTML.replace('value="{{user}}"', 'value="' + escapeAttr(currentUserName()) + '"');
    overlay.appendChild(iframe); hostDoc.body.appendChild(overlay);
  }
  function fallbackLatestMessageId() {
    const getter = runtimeFunction('getLastMessageId');
    if (getter) {
      try {
        const id = Number(getter());
        if (Number.isFinite(id) && id >= 0) return id;
      } catch (error) {}
    }
    const chat = getSillyTavern()?.chat;
    return Array.isArray(chat) && chat.length ? chat.length - 1 : -1;
  }

  function currentChatId() {
    const st = getSillyTavern();
    try {
      const value = st?.getCurrentChatId?.();
      if (value !== undefined && value !== null) return String(value);
    } catch (error) {}

    const getter = runtimeFunction('getCurrentChatId');
    if (getter) {
      try {
        const value = getter();
        if (value !== undefined && value !== null) return String(value);
      } catch (error) {}
    }

    try {
      const ctx = st?.getContext?.();
      const value = ctx?.groupId ?? ctx?.group_id ?? ctx?.chatId ?? ctx?.chat_id;
      if (value !== undefined && value !== null) return String(value);
    } catch (error) {}
    return '';
  }

  function fallbackBranchToken(id) {
    const chat = getSillyTavern()?.chat;
    const message = chat?.[id];
    const swipeId = message?.swipe_id ?? message?.swipeId ?? 0;
    return 'pending:' + currentChatId() + ':' + id + ':' + swipeId;
  }

  function messageContainsStartMarker(message) {
    if (!message) return false;
    const values = [
      message?.mes,
      message?.message,
      message?.text,
      message?.content,
      ...(Array.isArray(message?.swipes) ? message.swipes : []),
    ];
    return values.some(value => /<GameStartMenu\s*\/>/i.test(String(value || '')));
  }

  function chatHasStartMarker() {
    const chat = getSillyTavern()?.chat;
    if (!Array.isArray(chat) || !chat.length) return false;

    const head = chat.slice(0, Math.min(chat.length, 32));
    if (head.some(messageContainsStartMarker)) return true;

    const tailStart = Math.max(32, chat.length - 8);
    return chat.slice(tailStart).some(messageContainsStartMarker);
  }

  async function refresh() {
    if (disposed) return;

    const api = getApi();

    if (!api?.readVariables) {
      const id = fallbackLatestMessageId();
      if (id >= 0 && chatHasStartMarker()) showOverlay(fallbackBranchToken(id), true);
      else removeOverlay();
      return;
    }

    const id = api.latestMessageId();

    if (id < 0) {
      const fallbackId = fallbackLatestMessageId();
      if (fallbackId >= 0 && chatHasStartMarker()) showOverlay(fallbackBranchToken(fallbackId), true);
      else removeOverlay();
      return;
    }

    const token = api.branchToken(id);
    let vars = api.readVariables(id);

    if (!vars?.stat_data) {
      await api.ensureLatestState();
      vars = api.readVariables(id);
    }

    if (!vars?.stat_data) {
      if (chatHasStartMarker()) showOverlay(token, true);
      else removeOverlay();
      return;
    }

    if (vars.stat_data.GameStarted === true) {
      removeOverlay();
      return;
    }

    showOverlay(token, false);
  }

  function applyStartPayload(state, payload) {
    const world = state.World; const mc = state.Mainchar;
    tupleSet(world, 'Date', payload.date, 'Date'); tupleSet(world, 'Time', payload.time, 'Time');
    tupleSet(world, 'Weather', payload.weather, 'Weather'); tupleSet(world, 'Location', payload.location, 'Location');
    tupleSet(mc, 'Name', payload.name, 'Name'); tupleSet(mc, 'Age', payload.age, 'Age'); tupleSet(mc, 'Gender', payload.gender, 'Gender');
    tupleSet(mc, 'Race', payload.race, 'Race'); tupleSet(mc, 'Occupation', payload.occupation, 'Occupation'); tupleSet(mc, 'Mental_state', payload.mental, 'Mental State');
    const stats = payload.stats || {}; const level = Math.max(1, Math.min(140, Number(payload.level) || 1));
    const str = Math.max(5, Number(stats.str) || 5), agi = Math.max(5, Number(stats.agi) || 5), con = Math.max(5, Number(stats.con) || 5);
    const intel = Math.max(5, Number(stats.int) || 5), wis = Math.max(5, Number(stats.wis) || 5), cha = Math.max(80, Math.min(100, Number(payload.charisma) || 80));
    tupleSet(mc, 'Level', level, 'Level'); tupleSet(mc, 'Exp', Math.max(0, Number(payload.exp) || 0), 'Experience'); tupleSet(mc, 'Core-points', Math.max(0, Number(payload.core) || 0), 'Unassigned Points');
    tupleSet(mc, 'Strength', str, 'Strength'); tupleSet(mc, 'Agility', agi, 'Agility'); tupleSet(mc, 'Constitution', con, 'Constitution'); tupleSet(mc, 'Intelligence', intel, 'Intelligence'); tupleSet(mc, 'Wisdom', wis, 'Wisdom'); tupleSet(mc, 'Charisma', cha, 'Charisma');
    const hp = Math.floor(20 + con * 3 + level * 6); const stamina = Math.floor(50 + con * 3 + agi * 2 + Math.floor(level * 5 / 3)); const mp = Math.floor((50 + intel * 4 + wis * 2 + level * 5) / 3);
    tupleSet(mc, 'Hp_max', hp, 'Max HP'); tupleSet(mc, 'Hp_curr', hp, 'Current HP'); tupleSet(mc, 'Sta_max', stamina, 'Max Stamina'); tupleSet(mc, 'Sta_curr', stamina, 'Current Stamina'); tupleSet(mc, 'Mp_max', mp, 'Max MP'); tupleSet(mc, 'Mp_curr', mp, 'Current MP');
    tupleSet(mc, 'Physical_attack', Math.floor(str * 2 + level * 2), 'Physical Attack'); tupleSet(mc, 'Magic_attack', Math.floor(intel * 2 + level * 2), 'Magic Attack'); tupleSet(mc, 'Physical_defense', Math.floor(con / 2 + level * 3), 'Physical Defense'); tupleSet(mc, 'Magic_defense', Math.floor(wis / 2 + level * 3), 'Magic Defense'); tupleSet(mc, 'Magic_assist', Math.floor(wis * 1.5 + intel * .5 + level * 1.5), 'Magic Support');
    mc.Inventory ||= {}; mc.Equipment ||= {}; for (const key of ['Beginner Sword', 'Beginner Staff']) { delete mc.Inventory[key]; delete mc.Equipment[key]; }
    const request = String(payload.weaponRequest || '').trim(); tupleSet(mc, 'Starting_weapon_request', request, 'One-shot starting weapon preference'); tupleSet(mc, 'Starting_weapon_status', request ? 'pending' : 'none', 'none | pending | fulfilled');
    state.Narrative.Scene.LocationKey = payload.location; state.Narrative.Scene.Changed = true; state.GameStarted = true; return state;
  }
  async function saveStart(payload, sourceWindow) {
    const api = getApi(); if (!api) throw new Error('FF + MVU Core is not ready');
    const normalizedTime = normalizeClock(payload?.time);
    if (!normalizedTime) throw new Error('Time must use a valid 24-hour H:MM or HH:MM value');
    payload = { ...(payload || {}), time: normalizedTime };
    const charisma = Number(payload.charisma);
    if (!Number.isInteger(charisma) || charisma < 80 || charisma > 100) throw new Error('Charisma must be an integer from 80 to 100');
    const id = api.latestMessageId();
    if (id < 0 || api.branchToken(id) !== activeToken) throw new Error('The active chat branch changed; reopen the menu');
    const vars = api.readVariables(id) || {}; const state = api.normalizeState(vars.stat_data || api.createDefaultState());
    applyStartPayload(state, payload);
    const errors = api.validateState(state); if (errors.length) throw new Error(errors.join('; '));
    if (typeof api.commitExternalState === 'function') await api.commitExternalState(id, state, 'gamestart');
    else {
      const prepared = api.prepareState(state); const fallbackErrors = api.validateState(prepared.state); if (fallbackErrors.length) throw new Error(fallbackErrors.join('; '));
      vars.stat_data = prepared.state; vars.ff_mvu_prompt_view = prepared.view; await api.writeVariables(id, vars);
    }
    sourceWindow?.postMessage({ type: 'FFMVU_GAMESTART_OK' }, '*'); removeOverlay();
  }
  async function onMessage(event) {
    if (event.data?.type !== 'FFMVU_GAMESTART_SAVE' || event.source !== iframe?.contentWindow) return;
    try { await saveStart(clone(event.data.payload), event.source); }
    catch (error) { console.error('[FFMVU GameStart]', error); event.source?.postMessage({ type: 'FFMVU_GAMESTART_ERROR', message: error.message }, '*'); }
  }
  function subscribe(eventName, handler) {
    if (!eventName) return;
    const on = runtimeFunction('eventOn');
    if (!on) return;

    on(eventName, handler);
    subscriptions.push(() => {
      try {
        const remove = runtimeFunction('eventRemoveListener');
        remove?.(eventName, handler);
      } catch (error) {}
    });
  }

  async function initialize() {
    const events = getTavernEvents();
    const schedule = () => {
      setTimeout(refresh, 40);
      setTimeout(refresh, 180);
      setTimeout(refresh, 600);
    };

    const names = [
      'CHAT_CHANGED',
      'MESSAGE_SWIPED',
      'MESSAGE_DELETED',
      'MESSAGE_EDITED',
      'MESSAGE_UPDATED',
      'MESSAGE_RECEIVED',
      'MESSAGE_SENT',
      'GROUP_UPDATED',
      'GROUP_MEMBER_DRAFTED',
      'GROUP_WRAPPER_FINISHED',
    ];

    for (const eventName of [...new Set(names.map(name => events[name]).filter(Boolean))]) {
      subscribe(eventName, schedule);
    }

    host.addEventListener('message', onMessage);
    poll = setInterval(refresh, 750);
    await refresh();
  }

  function cleanup() {
    if (disposed) return; disposed = true; if (poll) clearInterval(poll); while (subscriptions.length) subscriptions.pop()();
    host.removeEventListener('message', onMessage); removeOverlay(); if (host.__FFMVU_GAMESTART_CLEANUP__ === cleanup) delete host.__FFMVU_GAMESTART_CLEANUP__;
  }
  host.__FFMVU_GAMESTART_CLEANUP__ = cleanup;
  scriptWindow.addEventListener('pagehide', cleanup, { once: true });
  setTimeout(initialize, 250);
})();
